def unit_of_work(metadata=None, timeout=None):
    """
    Returns a decorator with metadata and timeout attributes.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            start_time = time.time()
            with context_manager(timeout) as cm:
                result = func(*args, **kwargs)
                cm.update_metadata({"execution_time": time.time() - start_time})
                if metadata:
                    cm.update_metadata(metadata)
                return result
        return wrapper
    return decorator

@contextlib.contextmanager
def context_manager(timeout):
    """
    Context manager to handle timeout and metadata.
    """
    metadata = {}
    if timeout:
        def timeout_handler(signum, frame):
            raise TimeoutError("Function execution timed out")
        signal.signal(signal.SIGALRM, timeout_handler)
        signal.alarm(timeout)

    try:
        yield metadata
    finally:
        if timeout:
            signal.alarm(0)

    return metadata

