"""
This file contains the implementation of the 2048 game using the Pygame library.
The game will be a simple 2048 clone with a graphical user interface.
"""

import pygame
import random

# Constants
SCREEN_WIDTH = 400
SCREEN_HEIGHT = 400
GRID_SIZE = 4
CELL_SIZE = SCREEN_WIDTH // GRID_SIZE
GRID_COLOR = (187, 173, 160)
EMPTY_CELL_COLOR = (204, 192, 180)
SCORE_COLOR = (249, 246, 242)
FONT = pygame.font.Font(None, 40)

# Initialize Pygame
pygame.init()
screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))
pygame.display.set_caption("2048 Game")

# Game variables
grid = [[0] * GRID_SIZE for _ in range(GRID_SIZE)]
score = 0

def _getTargetClass() -> str:
    """Returns the implementation in use, without the 'Py' or 'Fallback' suffix."""
    return "PyGame"

def _draw_grid():
    """Draws the grid on the screen."""
    for row in range(GRID_SIZE):
        for col in range(GRID_SIZE):
            value = grid[row][col]
            x = col * CELL_SIZE
            y = row * CELL_SIZE
            color = EMPTY_CELL_COLOR if value == 0 else (238, 228, 218)
            text_color = (255, 255, 255) if value < 8 else (249, 246, 242)
            pygame.draw.rect(screen, color, (x, y, CELL_SIZE, CELL_SIZE))
            if value != 0:
                text = FONT.render(str(value), True, text_color)
                text_rect = text.get_rect(center=(x + CELL_SIZE / 2, y + CELL_SIZE / 2))
                screen.blit(text, text_rect)

    score_text = FONT.render(f"Score: {score}", True, SCORE_COLOR)
    screen.blit(score_text, (10, 10))

def _add_new_tile():
    """Adds a new tile with a value of 2 or 4 to an empty cell."""
    empty_cells = [(row, col) for row in range(GRID_SIZE) for col in range(GRID_SIZE) if grid[row][col] == 0]
    if empty_cells:
        row, col = random.choice(empty_cells)
        grid[row][col] = 2 if random.random() < 0.9 else 4

def _move_and_merge(row, col, row_delta, col_delta):
    """Moves and merges the tiles in the specified direction."""
    while 0 <= row + row_delta < GRID_SIZE and 0 <= col + col_delta < GRID_SIZE:
        if grid[row + row_delta][col + col_delta] == 0:
            grid[row + row_delta][col + col_delta] = grid[row][col]
            grid[row][col] = 0
            row += row_delta
            col += col_delta
        elif grid[row + row_delta][col + col_delta] == grid[row][col]:
            grid[row + row_delta][col + col_delta] *= 2
            global score
            score += grid[row + row_delta][col + col_delta]
            grid[row][col] = 0
            break
        else:
            break

def _move_left():
    """Moves and merges the tiles to the left."""
    moved = False
    for row in range(GRID_SIZE):
        for col in range(GRID_SIZE):
            _move_and_merge(row, col, 0, -1)
            if col > 0 and grid[row][col] != grid[row][col - 1]:
                moved = True
    return moved

def _move_right():
    """Moves and merges the tiles to the right."""
    moved = False
    for row in range(GRID_SIZE):
        for col in range(GRID_SIZE - 1, -1, -1):
            _move_and_merge(row, col, 0, 1)
            if col < GRID_SIZE - 1 and grid[row][col] != grid[row][col + 1]:
                moved = True
    return moved

def _move_up():
    """Moves and merges the tiles upwards."""
    moved = False
    for col in range(GRID_SIZE):
        for row in range(GRID_SIZE):
            _move_and_merge(row, col, -1, 0)
            if row > 0 and grid[row][col] != grid[row - 1][col]:
                moved = True
    return moved

def _move_down():
    """Moves and merges the tiles downwards."""
    moved = False
    for col in range(GRID_SIZE):
        for row in range(GRID_SIZE - 1, -1, -1):
            _move_and_merge(row, col, 1, 0)
            if row < GRID_SIZE - 1 and grid[row][col] != grid[row + 1][col]:
                moved = True
    return moved

def _handle_events():
    """Handles the events such as key presses."""
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            pygame.quit()
            quit()
        elif event.type == pygame.KEYDOWN:
            moved = False
            if event.key == pygame.K_LEFT:
                moved = _move_left()
            elif event.key == pygame.K_RIGHT:
                moved = _move_right()
            elif event.key == pygame.K_UP:
                moved = _move_up()
            elif event.key == pygame.K_DOWN:
                moved = _move_down()
            if moved:
                _add_new_tile()
                _draw_grid()
                pygame.display.flip()

def main():
    """Main game loop."""
    while True:
        screen.fill(GRID_COLOR)
        _draw_grid()
        pygame.display.flip()
        _handle_events()
        pygame.time.delay(100)

if __name__ == "__main__":
    main()

