        """
        Move the tiles up and merge them.
        """
        self._move_and_merge([list(row) for row in zip(*self.board)], lambda x: x)

    def move_down(self):
        """
        Move the tiles down and merge them.
        """
        self._move_and_merge([list(row) for row in zip(*self.board)], lambda x: x[::-1])

    def _move_and_merge(self, board, transform):
        """
        Helper method to move and merge the tiles in a given direction.
        """
        for row in board:
            transformed_row = transform(row)
            new_row = [cell for cell in transformed_row if cell != 0]
            for i in range(len(new_row) - 1):
                if new_row[i] == new_row[i + 1]:
                    new_row[i] *= 2
                    self.score += new_row[i]
                    new_row[i + 1] = 0
            new_row = [cell for cell in new_row if cell != 0]
            while len(new_row) < 4:
                new_row.append(0)
            row[:] = transform(new_row)

    def run(self):
        """
        Main game loop.
        """
        self.add_random_tile()
        self.add_random_tile()
        while True:
            self._print_board()
            move = input(): ").strip().lower()
            if move == 'left':
                self.move_left()
            elif move == 'right':
                self.move_right()
            elif move == 'up':
                self.move_up()
            elif move == 'down':
                self.move_down()
            else:
                print("Invalid move. Please try again.")
                continue
            self.add_random_tile()
            if self._is_game_over():
                self._print_board()
                print(f"Game over! Your score is: {self.score}")
                break

    def _print_board(self):
        """
        Print the current state of the board.
        """
        for row in self.board:
            print(' '.join(str(cell) if cell != 0 else '.' for cell in row))
        print(f"Score: {self.score}")

    def _is_game_over(self):
        """
        Check if the game is over (no more moves possible).
        """
        for row in self.board:
            if 0 in row:
                return False
        for row in self.board:
            for i in range(3):
                if row[i] == row[i + 1]:
                    return False
        for i in range(4):
            for j in range(3):
                if self.board[j][i] == self.board[j + 1][i]:
                    return False
        return True

