from typing import List
import zipfile
import os
from typing import Optional, Union
from pathlib import PosixPath

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    @param archive_path : archive file path
    @param filename: File name
    @param tmp_path: Temporary file path
    @return Repo URL
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive file at {archive_path} does not exist.")

    if filename is None:
        filename = os.path.basename(archive_path)

    if not os.path.isabs(tmp_path):
        tmp_path = os.path.abspath(tmp_path)

    extracted_path = os.path.join(tmp_path, filename.replace('.zip', ''))

    with zipfile.ZipFile(archive_path, 'r') as zip_ref:
        zip_ref.extractall(extracted_path)

    return f"file://{extracted_path}"

